import type { AlbumConfig, AlbumSlide, PageConfig } from "../types";
import { hasMedia, readPageMedia } from "./media";
import { buildWordCloud } from "./wordCloud";

export interface BuildSlidesOptions {
  /** Append the closing cover. Defaults to true. */
  showBackCover?: boolean;
}

/**
 * Compiles an album into the ordered leaf list every layout reads: the front
 * cover, each greeting in page order, an optional word cloud, then the back
 * cover.
 *
 * Shared rather than per-layout so anything rendering an album — the flip book,
 * the slider, the printed sheets — agrees on what the leaves are and how a
 * greeting carrying both a photo and a wish is divided between them.
 */
export function buildSlides(
  album: AlbumConfig,
  { showBackCover = true }: BuildSlidesOptions = {},
): AlbumSlide[] {
  const ordered = [...album.pages].sort((a, b) => a.order - b.order);
  const slides: AlbumSlide[] = [
    { kind: "front-cover", key: `${album.id}-front` },
    ...ordered.flatMap<AlbumSlide>(splitGreeting),
  ];

  // An album of photo-only greetings has nothing to gather, and a page reading
  // "not enough words yet" is worse than no page at all.
  if (album.showWordCloud && buildWordCloud(album).length > 0) {
    slides.push({ kind: "word-cloud", key: `${album.id}-cloud` });
  }

  if (showBackCover) {
    slides.push({ kind: "back-cover", key: `${album.id}-back` });
  }
  return slides;
}

/**
 * A greeting that has both a wish and something to watch becomes two pages —
 * the words first, then the media (a video player or a photo collage) — because
 * a single page has to shrink both to fit one. Anything carrying only one of
 * the two is left as a single page.
 *
 * A page that names its photo layout was composed as one leaf (the place's
 * words beside a chosen grid), so the words stay with the pictures.
 */
function splitGreeting(page: PageConfig): AlbumSlide[] {
  const hasText = hasWords(page.html);
  const hasVisual = hasMedia(readPageMedia(page));

  if (!hasText || !hasVisual || page.photoLayout) {
    return [{ kind: "page", key: page.id, page }];
  }

  return [
    { kind: "page", key: `${page.id}-text`, page, part: "text" },
    { kind: "page", key: `${page.id}-photo`, page, part: "photo" },
  ];
}

/**
 * Whether a greeting says anything, ignoring its markup. An editor leaves an
 * empty paragraph behind when the last word is deleted, and that must not count
 * as a wish worth splitting a photo away from.
 */
function hasWords(html: string): boolean {
  return html.replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim().length > 0;
}
